import { randomUUID } from 'crypto';
import { normalizeRow } from '@/lib/examtrackerNormalize';

/**
 * vendor_questions.year / order_index are INTEGER.
 * Platform examtracker may store labels like "generated by 10tracker" in year —
 * coerce those (and any non-numeric value) to null instead of failing the insert.
 */
export function toIntOrNull(value) {
  if (value === undefined || value === null) return null;
  if (typeof value === 'string' && value.trim() === '') return null;
  const n = Number(value);
  if (!Number.isFinite(n)) return null;
  return Math.trunc(n);
}

/**
 * Normalize a question for vendor_questions (same fields as examtracker + vendor meta).
 * Always assigns a new _id unless keepId is true (updates).
 */
export function normalizeVendorQuestion(raw, { defaults = {}, keepId = false, forceNewId = false } = {}) {
  const n = normalizeRow(raw, defaults);
  if (!n.ok) return n;

  const row = { ...n.row };
  if (forceNewId || (!keepId && !raw?._id && !raw?.id)) {
    row._id = randomUUID();
  } else if (forceNewId) {
    row._id = randomUUID();
  }

  // NAT: normalizeRow uppercases correct_option — restore trimmed original for non A-D
  const originalCorrect = raw?.correct_option ?? raw?.correctOption;
  if (originalCorrect != null && String(originalCorrect).trim()) {
    const c = String(originalCorrect).trim();
    if (!/^[A-Da-d]$/.test(c) && !c.includes('|')) {
      row.correct_option = c;
    } else if (c.includes('|')) {
      row.correct_option = c
        .split('|')
        .map((p) => p.trim())
        .filter(Boolean)
        .join('|');
    }
  }

  // INTEGER columns — never keep non-numeric strings from examtracker
  row.year = toIntOrNull(row.year);
  row.order_index = toIntOrNull(row.order_index);

  return { ok: true, row };
}

/**
 * Maps examtracker-shaped rows onto vendor_questions columns.
 *
 * Unquoted mixed-case in CREATE TABLE is folded by Postgres
 * (options_A → options_a, directionHTML → directionhtml). PostgREST keys
 * must match the folded names exactly.
 */
export function toVendorQuestionInsert(row, { vendorId, source, sourceQuestionId, createdBy }) {
  return {
    _id: row._id,
    vendor_id: vendorId,
    topic: row.topic,
    category: row.category,
    difficulty: row.difficulty || 'easy',
    year: toIntOrNull(row.year),
    subject: row.subject ?? null,
    chapter: row.chapter ?? null,
    question: row.question,
    options_a: row.options_A ?? row.options_a ?? null,
    options_b: row.options_B ?? row.options_b ?? null,
    options_c: row.options_C ?? row.options_c ?? null,
    options_d: row.options_D ?? row.options_d ?? null,
    correct_option: row.correct_option ?? null,
    solution: row.solution ?? null,
    solutiontext: row.solutiontext ?? null,
    directionhtml: row.directionHTML ?? row.direction_html ?? row.directionhtml ?? null,
    questionimage: row.questionImage ?? row.question_image ?? row.questionimage ?? null,
    questioncode: row.questionCode ?? row.question_code ?? row.questioncode ?? null,
    topiclist: row.topicList ?? row.topic_list ?? row.topiclist ?? null,
    order_index: toIntOrNull(row.order_index),
    source: source || 'manual',
    source_question_id: sourceQuestionId || null,
    created_by: createdBy || null,
    updated_at: new Date().toISOString(),
  };
}

/** Map DB row (lowercase option cols) back to examtracker-shaped keys for UI/API. */
export function fromVendorQuestionRow(row) {
  if (!row || typeof row !== 'object') return row;
  return {
    ...row,
    options_A: row.options_A ?? row.options_a ?? null,
    options_B: row.options_B ?? row.options_b ?? null,
    options_C: row.options_C ?? row.options_c ?? null,
    options_D: row.options_D ?? row.options_d ?? null,
    directionHTML: row.directionHTML ?? row.directionhtml ?? null,
    questionImage: row.questionImage ?? row.questionimage ?? null,
    questionCode: row.questionCode ?? row.questioncode ?? null,
    topicList: row.topicList ?? row.topiclist ?? null,
  };
}

/** Normalize question HTML/text for duplicate detection within a vendor. */
export function normalizeQuestionText(html) {
  return String(html || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}
